// v1.1 – NovaWorks Planspiel
const simPanel=document.getElementById("simulationPanel");
const simBackdrop=document.getElementById("simulationBackdrop");
const openSim=()=>{simPanel?.classList.add("open");simBackdrop?.classList.add("open");simPanel?.setAttribute("aria-hidden","false");};
const closeSim=()=>{simPanel?.classList.remove("open");simBackdrop?.classList.remove("open");simPanel?.setAttribute("aria-hidden","true");};
document.getElementById("simulationBtn")?.addEventListener("click",openSim);
document.getElementById("closeSimulation")?.addEventListener("click",closeSim);
simBackdrop?.addEventListener("click",closeSim);
document.querySelectorAll(".sim-tab").forEach(btn=>btn.addEventListener("click",()=>{
 document.querySelectorAll(".sim-tab").forEach(x=>x.classList.remove("active"));
 document.querySelectorAll(".sim-pane").forEach(x=>x.classList.remove("active"));
 btn.classList.add("active");
 document.querySelector(`[data-pane="${btn.dataset.simtab}"]`)?.classList.add("active");
}));
document.querySelectorAll("[data-store]").forEach(el=>{
 const key="novaworks_"+el.dataset.store;
 el.value=localStorage.getItem(key)||"";
 el.addEventListener("input",()=>{
   localStorage.setItem(key,el.value);
   const s=document.getElementById("saveState"); if(s){s.textContent="gespeichert ✓";setTimeout(()=>s.textContent="lokal gespeichert",900);}
 });
});
document.getElementById("clearBoard")?.addEventListener("click",()=>{
 if(confirm("Alle Einträge im NovaWorks-Transformationsboard löschen?")){
   document.querySelectorAll("[data-store]").forEach(el=>{localStorage.removeItem("novaworks_"+el.dataset.store);el.value="";});
 }
});

// v1.2 – aufklappbare Musterlösung
document.querySelectorAll(".solution-toggle").forEach(btn=>{
  btn.addEventListener("click",e=>{
    e.stopPropagation();
    const box=btn.nextElementSibling;
    const willOpen=box.hasAttribute("hidden");
    if(willOpen) box.removeAttribute("hidden"); else box.setAttribute("hidden","");
    btn.textContent=willOpen?"Lösung / Einordnung verbergen":"Lösung / Einordnung anzeigen";
  });
});
document.querySelectorAll(".solution-box").forEach(box=>box.addEventListener("click",e=>e.stopPropagation()));

